CREATE TEMP TABLE palette_migration AS SELECT COUNT(*) AS post_palette FROM habits WHERE color >= 40;
UPDATE habits SET color = CASE color WHEN 0 THEN 1 WHEN 1 THEN 2 WHEN 2 THEN 0 WHEN 3 THEN 5 WHEN 4 THEN 6 WHEN 5 THEN 4 WHEN 6 THEN 5 WHEN 7 THEN 6 WHEN 8 THEN 4 WHEN 9 THEN 9 WHEN 10 THEN 10 WHEN 11 THEN 8 WHEN 12 THEN 9 WHEN 13 THEN 10 WHEN 14 THEN 8 WHEN 15 THEN 13 WHEN 16 THEN 14 WHEN 17 THEN 12 WHEN 18 THEN 21 WHEN 19 THEN 22 WHEN 20 THEN 20 WHEN 21 THEN 25 WHEN 22 THEN 26 WHEN 23 THEN 24 WHEN 24 THEN 29 WHEN 25 THEN 30 WHEN 26 THEN 28 WHEN 27 THEN 33 WHEN 28 THEN 34 WHEN 29 THEN 32 WHEN 30 THEN 41 WHEN 31 THEN 42 WHEN 32 THEN 40 WHEN 33 THEN 45 WHEN 34 THEN 46 WHEN 35 THEN 44 WHEN 36 THEN 49 WHEN 37 THEN 49 WHEN 38 THEN 50 WHEN 39 THEN 51 ELSE color END WHERE color < 40 AND (SELECT post_palette FROM palette_migration) = 0;
DROP TABLE palette_migration;
